mapper.select:
SELECT * FROM ( SELECT rownum rn, TB.* FROM ( SELECT , p.STITLE AS PROM_TITLE, p.SGUBUN_ID AS PROM_GUBUN_ID, c.SNAME AS CATE_NM, b.ORGNZT_NM AS BUSEO_NM,
CASE WHEN w.IPWRK_NO = ( SELECT MAX(w2.IPWRK_NO) FROM TB_PROM_WRK w2 WHERE w2.IPROM_NO = w.IPROM_NO ) THEN 'Y' ELSE 'N' END AS LATEST_YN,
( SELECT MAX(rd.IDUTY_NO) FROM TB_READ_DUTY rd WHERE rd.IPROM_NO = w.IPROM_NO ) AS DUTY_NO FROM TB_PROM_WRK w LEFT OUTER JOIN TB_PROM p ON w.IPROM_NO = p.IPROM_NO LEFT OUTER JOIN TB_CATE c ON p.ICATE_NO = c.ICATE_NO LEFT OUTER JOIN COMTNORGNZTINFO b ON b.ORGNZT_ID = NVL(p.SBUSEO_ORGNZT_ID, 'ORG_' || LPAD(TO_CHAR(p.IBUSEO_NO), 16, '0'))
AND w.IPWRK_NO = ( SELECT MAX(w2.IPWRK_NO) FROM TB_PROM_WRK w2 WHERE w2.IPROM_NO = w.IPROM_NO )
AND UPPER(w.SUSER_NM) LIKE '%' || UPPER(#{searchUserNm}) || '%'
AND w.SSTATUS = #{searchStatus}
AND w.SSTATUS = '승인요청' AND EXISTS ( SELECT 1 FROM TB_PROM px WHERE px.IPROM_NO = w.IPROM_NO )
AND w.SSTATUS = '승인반려' AND EXISTS ( SELECT 1 FROM TB_PROM px WHERE px.IPROM_NO = w.IPROM_NO ) AND ( SELECT r.SUSER_ID FROM TB_PROM_WRK r WHERE r.IPWRK_NO = ( SELECT MAX(r2.IPWRK_NO) FROM TB_PROM_WRK r2 WHERE r2.IPROM_NO = w.IPROM_NO AND r2.SSTATUS = '승인요청' ) ) = #{searchMyRejectedUserId}
AND w.SINS_DT >= #{searchFromDt}
AND w.SINS_DT < #{searchToDt} || ' 23:59:59'
ORDER BY w.SINS_DT DESC, w.IPWRK_NO DESC ) TB ) WHERE rn BETWEEN #{firstIndex}+1 AND #{firstIndex}+#{recordCountPerPage}

SELECT COUNT(*) FROM TB_PROM_WRK w
AND w.IPWRK_NO = ( SELECT MAX(w2.IPWRK_NO) FROM TB_PROM_WRK w2 WHERE w2.IPROM_NO = w.IPROM_NO )
AND UPPER(w.SUSER_NM) LIKE '%' || UPPER(#{searchUserNm}) || '%'
AND w.SSTATUS = #{searchStatus}
AND w.SSTATUS = '승인요청' AND EXISTS ( SELECT 1 FROM TB_PROM px WHERE px.IPROM_NO = w.IPROM_NO )
AND w.SSTATUS = '승인반려' AND EXISTS ( SELECT 1 FROM TB_PROM px WHERE px.IPROM_NO = w.IPROM_NO ) AND ( SELECT r.SUSER_ID FROM TB_PROM_WRK r WHERE r.IPWRK_NO = ( SELECT MAX(r2.IPWRK_NO) FROM TB_PROM_WRK r2 WHERE r2.IPROM_NO = w.IPROM_NO AND r2.SSTATUS = '승인요청' ) ) = #{searchMyRejectedUserId}
AND w.SINS_DT >= #{searchFromDt}
AND w.SINS_DT < #{searchToDt} || ' 23:59:59'

mapper.insert:
INSERT INTO TB_PROM_WRK (
	IPWRK_NO, IPROM_NO, SSTATUS,
	SUSER_ID, SUSER_NM, SINS_DT, SREASON, SACT_NM
) VALUES (
	#{workNo}, #{promNo}, #{status},
	NVL(#{userId,jdbcType=VARCHAR}, ' '),
	NVL(#{userNm,jdbcType=VARCHAR}, NVL(#{userId,jdbcType=VARCHAR}, ' ')),
	TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'),
	#{reason,jdbcType=CLOB}, #{actNm}
)
